var n=`0153-dolma-in-grape-leaves`;var a=`world-0153`;var t=`AZ`;var l=`western-asia`;var o=4;var r=108;var s={en:`Dolma in Grape Leaves`,ua:`Долма у виноградному листі`};var g={en:`A classic dish from Azerbaijan, featuring grape leaves, ground lamb, white rice, yellow onion. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Азербайджан. Основні складники: виноградне листя, фарш з ягнятини, білий рис, жовта цибуля. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Separate and blanch the leaves in hot water for about 5 minutes until pliable. Drain and trim thick ribs.`,ua:`Відокремте й бланшуйте листя в гарячій воді приблизно 5 хвилин до гнучкості. Обсушіть і зріжте товсті прожилки.`,t:[`blanching`],m:5,i:[[`grape-leaves`,260,`g`]]},{en:`Prepare the filling ingredients: cook or soften any components that require it, let cool, then mix into an even filling.`,ua:`Підготуйте складники начинки: ті, що потребують теплової обробки, приготуйте, охолодіть і змішайте в однорідну начинку.`,t:[`chopping`,`mixing`],m:10,i:[[`ground-lamb`,520,`g`],[`white-rice`,150,`g`],[`yellow-onion`,190,`g`],[`mint`,20,`g`],[`dill`,20,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]},{en:`Place a portion of prepared filling on each leaf or wrapper, tuck in the sides and roll tightly into neat parcels.`,ua:`Викладіть порцію готової начинки на кожен листок або обгортку, загорніть боки й скрутіть щільні акуратні рулетики.`,t:[`rolling-stuffed-food`],m:25,i:[]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`water`,650,`ml`],[`extra-virgin-olive-oil`,40,`ml`],[`lemon-juice`,25,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`plain-yogurt`,160,`g`]]}];var u={slug:n,id:a,country:`AZ`,region:l,servings:4,minutes:108,title:s,text:g,steps:d};export{t as country,u as default,a as id,r as minutes,l as region,o as servings,n as slug,d as steps,g as text,s as title};